+/**
+ * A text file based implementation of a {@link ViolationStore}.<br>
+ * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
+ * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
+ * <p>
+ * The standard layout within the configured store folder is:
+ * <pre><code>
+ * storeFolder
+ *   |-- stored.rules (the index file of all stored rules)
+ *   |-- 6fc2fd04-b3ab-44e0-8f78-215c66f2174a (a rule violation file referenced from stored.rules)
+ * </code></pre>
+ *
+ * <p>This {@link ViolationStore} can be configured through the following properties:
+ * <pre><code>
+ * default.path=...               # string: the path of the folder where violation files will be stored
+ * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
+ * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
+ * default.fileNames=...           # random, description, or a RuleViolationFileNameStrategy class
+ * default.integrity=...           # ignore, repair, or fail
+ * </code></pre>
+ */
+@PublicAPI(usage = ACCESS)
+public final class TextFileBasedViolationStore implements ViolationStore {
+    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);
+
+    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
+    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile("[A-Za-z0-9]{4,}");
+    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
+    private static final String STORE_PATH_DEFAULT = "archunit_store";
+    private static final String STORED_RULES_FILE_NAME = "stored.rules";
+    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
+    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
+    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
+    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
+    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
+    private static final String FILE_NAMES_RANDOM = "random";
+    private static final String FILE_NAMES_DESCRIPTION = "description";
+    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
+    private static final String INTEGRITY_IGNORE = "ignore";
+    private static final String INTEGRITY_REPAIR = "repair";
+    private static final String INTEGRITY_FAIL = "fail";
+    private static final int MAX_BUILT_IN_FILE_NAME_LENGTH = 200;
+
+    private static final ConcurrentHashMap<String, StoreState> STORE_STATES_BY_PATH = new ConcurrentHashMap<>();
+
+    private final RuleViolationFileNameStrategy constructorStrategy;
+    private final boolean hasConstructorStrategy;
+
+    private boolean storeCreationAllowed;
+    private boolean storeUpdateAllowed;
+    private IntegrityMode integrityMode;
+    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
+    private File storeFolder;
+    private StoreState storeState;
+
+    /**
+     * Creates a standard {@link TextFileBasedViolationStore} that names rule violation files by random {@link UUID}s.
+     *
+     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
+     */
+    public TextFileBasedViolationStore() {
+        constructorStrategy = __ -> UUID.randomUUID().toString();
+        hasConstructorStrategy = false;
+    }
+
+    /**
+     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming.
+     *
+     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
+     */
+    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
+        if (ruleViolationFileNameStrategy == null) {
+            throw new IllegalArgumentException("The rule violation file name strategy must not be null");
+        }
+        constructorStrategy = ruleViolationFileNameStrategy;
+        hasConstructorStrategy = true;
+    }
+
+    @Override
+    public void initialize(Properties properties) {
+        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        integrityMode = IntegrityMode.from(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_IGNORE));
+        ruleViolationFileNameStrategy = configureFileNameStrategy(properties);
+
+        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Integrity repair requires %s.%s=true",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        try {
+            storeFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT)).getCanonicalFile();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+
+        StoreState state = getStoreState(storeFolder);
+        synchronized (state) {
+            File storedRulesFile = state.storedRulesFile;
+            log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesFile.getAbsolutePath());
+            ensureStoreFolderExists();
+            boolean indexExisted = existsWithoutFollowingLinks(storedRulesFile.toPath());
+            ensureStoredRulesFile(storedRulesFile, indexExisted);
+
+            FileSyncedProperties loadedRules = FileSyncedProperties.load(storedRulesFile);
+            IntegrityReport report = integrityMode == IntegrityMode.IGNORE
+                    ? IntegrityReport.empty()
+                    : analyzeIntegrity(loadedRules);
+            if (integrityMode == IntegrityMode.FAIL && report.hasProblems()) {
+                throw new StoreInitializationFailedException(report.message(storedRulesFile));
+            }
+
+            if (integrityMode == IntegrityMode.REPAIR) {
+                repair(report, loadedRules);
+            }
+            state.storedRules = loadedRules;
+            storeState = state;
+        }
+    }
+
+    private RuleViolationFileNameStrategy configureFileNameStrategy(Properties properties) {
+        if (hasConstructorStrategy) {
+            if (properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "%s cannot be configured for a store constructed with a RuleViolationFileNameStrategy",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            return constructorStrategy;
+        }
+
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_RANDOM);
+        if (FILE_NAMES_RANDOM.equals(configured)) {
+            return constructorStrategy;
+        }
+        if (FILE_NAMES_DESCRIPTION.equals(configured)) {
+            return TextFileBasedViolationStore::createDescriptionBasedFileName;
+        }
+        try {
+            Class<?> strategyType = Class.forName(configured);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyType)
+                    || !Modifier.isPublic(strategyType.getModifiers())) {
+                throw new IllegalArgumentException("not a public RuleViolationFileNameStrategy");
+            }
+            Constructor<?> constructor = strategyType.getConstructor();
+            if (!Modifier.isPublic(constructor.getModifiers())) {
+                throw new IllegalArgumentException("does not have a public no-argument constructor");
+            }
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Invalid %s '%s'; accepted values are 'random', 'description', or a public RuleViolationFileNameStrategy with a public no-argument constructor",
+                    FILE_NAMES_PROPERTY_NAME, configured), e);
+        }
+    }
+
+    private StoreState getStoreState(File folder) {
+        try {
+            String path = new File(folder, STORED_RULES_FILE_NAME).getCanonicalPath();
+            return STORE_STATES_BY_PATH.computeIfAbsent(path, ignored -> new StoreState(folder, new File(folder, STORED_RULES_FILE_NAME)));
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void ensureStoreFolderExists() {
+        Path folderPath = storeFolder.toPath();
+        try {
+            if (!existsWithoutFollowingLinks(folderPath)) {
+                if (!storeFolder.mkdirs() && !isDirectoryWithoutFollowingLinks(folderPath)) {
+                    throw new IOException("Could not create store folder " + storeFolder);
+                }
+            }
+            if (!isDirectoryWithoutFollowingLinks(folderPath)) {
+                throw new IOException("Store path is not a directory: " + storeFolder);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void ensureStoredRulesFile(File storedRulesFile, boolean indexExisted) {
+        Path indexPath = storedRulesFile.toPath();
+        if (!indexExisted) {
+            if (!storeCreationAllowed || integrityMode == IntegrityMode.FAIL) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+            }
+            try {
+                if (!storedRulesFile.createNewFile() && !existsWithoutFollowingLinks(indexPath)) {
+                    throw new IOException("Could not create index file " + storedRulesFile);
+                }
+            } catch (IOException e) {
+                throw new StoreInitializationFailedException(e);
+            }
+        }
+
+        try {
+            Path folderPath = storeFolder.toPath().toAbsolutePath().normalize();
+            Path indexAbsolutePath = indexPath.toAbsolutePath().normalize();
+            if (!indexAbsolutePath.getParent().equals(folderPath)
+                    || !Files.isRegularFile(indexPath, LinkOption.NOFOLLOW_LINKS)) {
+                throw new IOException("Index is not a regular file directly in the store folder");
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Violation store index must be a regular file directly in %s: %s", storeFolder, storedRulesFile));
+        }
+    }
+
+    private IntegrityReport analyzeIntegrity(FileSyncedProperties rules) {
+        List<EntryAnalysis> entries = rules.entries().stream()
+                .sorted(Comparator.comparing(entry -> entry.description))
+                .map(entry -> analyzeEntry(entry, rules))
+                .collect(toList());
+
+        Map<String, List<EntryAnalysis>> entriesByRecordedName = groupBy(entries, entry -> entry.recordedName);
+        Map<String, List<EntryAnalysis>> entriesByTarget = groupBy(entries, entry -> entry.target == null ? null : entry.target.toString());
+        Map<String, List<EntryAnalysis>> entriesByDerivedName = groupBy(entries, entry -> entry.derivedName);
+
+        for (EntryAnalysis entry : entries) {
+            List<EntryAnalysis> sameName = entriesByRecordedName.get(entry.recordedName);
+            List<EntryAnalysis> sameTarget = entry.target == null ? null : entriesByTarget.get(entry.target.toString());
+            entry.shared = sameName.size() > 1 || sameTarget != null && sameTarget.size() > 1;
+            List<EntryAnalysis> sameDerivedName = entry.derivedName == null ? null : entriesByDerivedName.get(entry.derivedName);
+            entry.colliding = sameDerivedName != null && sameDerivedName.size() > 1;
+        }
+
+        Set<String> recordedNames = new HashSet<>();
+        for (EntryAnalysis entry : entries) {
+            recordedNames.add(entry.recordedName);
+        }
+        for (EntryAnalysis entry : entries) {
+            entry.occupied = isOccupied(entry, recordedNames, entries);
+        }
+
+        List<File> unownedFiles = findUnownedFiles(entries);
+        return new IntegrityReport(entries, unownedFiles);
+    }
+
+    private EntryAnalysis analyzeEntry(IndexEntry entry, FileSyncedProperties rules) {
+        EntryAnalysis result = new EntryAnalysis(entry);
+        result.path = resolvePath(entry.recordedName);
+        result.target = result.path.realPath;
+        result.broken = result.path.broken;
+        result.derivedName = deriveName(entry.description);
+        result.misplaced = !isRandomNaming() && !entry.recordedName.equals(result.derivedName);
+
+        if (!result.broken && isIndex(result.target)) {
+            result.broken = true;
+        }
+        if (!result.broken) {
+            try {
+                result.resolved = readLines(result.target).isEmpty();
+            } catch (RuntimeException e) {
+                result.broken = true;
+            }
+        }
+        return result;
+    }
+
+    private boolean isOccupied(EntryAnalysis entry, Set<String> recordedNames, List<EntryAnalysis> entries) {
+        if (entry.derivedName == null) {
+            return true;
+        }
+        Path derivedPath = resolvePath(entry.derivedName).realPath;
+        if (derivedPath == null || !isDirectChild(derivedPath) || isIndex(derivedPath)) {
+            return true;
+        }
+
+        for (EntryAnalysis other : entries) {
+            if (other != entry && entry.derivedName.equals(other.recordedName)) {
+                return true;
+            }
+        }
+
+        Path source = entry.target;
+        if (!existsWithoutFollowingLinks(derivedPath)) {
+            return false;
+        }
+        if (source != null && sameFile(source, derivedPath)) {
+            return false;
+        }
+        return true;
+    }
+
+    private List<File> findUnownedFiles(List<EntryAnalysis> entries) {
+        List<File> result = new ArrayList<>();
+        Set<Path> ownedTargets = new HashSet<>();
+        for (EntryAnalysis entry : entries) {
+            if (!entry.broken && entry.target != null && Files.isRegularFile(entry.target)) {
+                ownedTargets.add(entry.target);
+            }
+        }
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(storeFolder.toPath())) {
+            for (Path file : files) {
+                if (isIndex(file) || !Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)) {
+                    continue;
+                }
+                boolean owned = ownedTargets.stream().anyMatch(target -> sameFile(target, file));
+                if (!owned) {
+                    result.add(file.toFile());
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        result.sort(Comparator.comparing(File::getName));
+        return result;
+    }
+
+    private void repair(IntegrityReport report, FileSyncedProperties rules) {
+        boolean changed = false;
+        for (EntryAnalysis entry : report.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                rules.remove(entry.description);
+                changed = true;
+            } else if (entry.resolved) {
+                deleteEntryFile(entry);
+                rules.remove(entry.description);
+                changed = true;
+            }
+        }
+
+        for (EntryAnalysis entry : report.entries) {
+            if (entry.shared || entry.broken || entry.resolved || !entry.misplaced || entry.colliding || entry.occupied) {
+                continue;
+            }
+            moveEntryFile(entry);
+            rules.set(entry.description, entry.derivedName);
+            changed = true;
+        }
+        if (changed) {
+            rules.syncFileSystem();
+        }
+    }
+
+    private void deleteEntryFile(EntryAnalysis entry) {
+        if (entry.target == null || isIndex(entry.target)) {
+            return;
+        }
+        try {
+            Files.deleteIfExists(entry.target);
+            if (entry.path.recordedPath != null && !samePath(entry.path.recordedPath, entry.target)
+                    && Files.isSymbolicLink(entry.path.recordedPath)) {
+                Files.deleteIfExists(entry.path.recordedPath);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not delete resolved violation file for rule '%s'", entry.description), e);
+        }
+    }
+
+    private void moveEntryFile(EntryAnalysis entry) {
+        Path source = entry.target;
+        Path destination = resolvePath(entry.derivedName).recordedPath;
+        if (source == null || destination == null || !isDirectChild(destination) || isIndex(destination)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot move violation file for rule '%s' to '%s'", entry.description, entry.derivedName));
+        }
+        try {
+            if (!sameFile(source, destination)) {
+                Files.move(source, destination, StandardCopyOption.ATOMIC_MOVE);
+            }
+            if (entry.path.recordedPath != null && !samePath(entry.path.recordedPath, source)
+                    && Files.isSymbolicLink(entry.path.recordedPath)) {
+                Files.deleteIfExists(entry.path.recordedPath);
+            }
+        } catch (IOException atomicMoveFailure) {
+            try {
+                if (!sameFile(source, destination)) {
+                    Files.move(source, destination);
+                }
+                if (entry.path.recordedPath != null && !samePath(entry.path.recordedPath, source)
+                        && Files.isSymbolicLink(entry.path.recordedPath)) {
+                    Files.deleteIfExists(entry.path.recordedPath);
+                }
+            } catch (IOException e) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Could not move violation file for rule '%s' to '%s'", entry.description, entry.derivedName), e);
+            }
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        return storeState.storedRules.containsKey(rule.getDescription());
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+        synchronized (storeState) {
+            if (integrityMode == IntegrityMode.REPAIR && violations.isEmpty()) {
+                forgetRuleIfKnown(rule.getDescription());
+                return;
+            }
+
+            String ruleDescription = rule.getDescription();
+            String existingFileName = storeState.storedRules.getProperty(ruleDescription);
+            String ruleFileName = existingFileName == null ? deriveName(ruleDescription) : existingFileName;
+            validateSavePath(ruleFileName, existingFileName);
+            Path ruleDetails = storeFolder.toPath().resolve(ruleFileName).normalize();
+            write(violations, ruleDetails, existingFileName != null);
+            if (existingFileName == null) {
+                storeState.storedRules.set(ruleDescription, ruleFileName);
+                storeState.storedRules.syncFileSystem();
+            }
+        }
+    }
+
+    private void forgetRuleIfKnown(String ruleDescription) {
+        String existingFileName = storeState.storedRules.getProperty(ruleDescription);
+        if (existingFileName == null) {
+            return;
+        }
+
+        EntryAnalysis entry = analyzeEntry(new IndexEntry(ruleDescription, existingFileName), storeState.storedRules);
+        boolean shared = storeState.storedRules.entries().stream()
+                .filter(other -> !other.description.equals(ruleDescription))
+                .map(other -> analyzeEntry(other, storeState.storedRules))
+                .anyMatch(other -> sharesFile(entry, other));
+        if (!shared && !entry.broken) {
+            deleteEntryFile(entry);
+        }
+        storeState.storedRules.remove(ruleDescription);
+        storeState.storedRules.syncFileSystem();
+    }
+
+    private boolean sharesFile(EntryAnalysis first, EntryAnalysis second) {
+        return first.target != null && second.target != null && sameFile(first.target, second.target)
+                || first.recordedName.equals(second.recordedName);
+    }
