+            storeState = state;
+        }
+    }
+
+    private RuleViolationFileNameStrategy configureFileNameStrategy(Properties properties) {
+        if (hasConstructorStrategy) {
+            if (properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "%s cannot be configured for a store constructed with a RuleViolationFileNameStrategy",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            return constructorStrategy;
+        }
+
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_RANDOM);
+        if (FILE_NAMES_RANDOM.equals(configured)) {
+            return constructorStrategy;
+        }
+        if (FILE_NAMES_DESCRIPTION.equals(configured)) {
+            return TextFileBasedViolationStore::createDescriptionBasedFileName;
+        }
+        try {
+            Class<?> strategyType = Class.forName(configured);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyType)
+                    || !Modifier.isPublic(strategyType.getModifiers())) {
+                throw new IllegalArgumentException("not a public RuleViolationFileNameStrategy");
+            }
+            Constructor<?> constructor = strategyType.getConstructor();
+            if (!Modifier.isPublic(constructor.getModifiers())) {
+                throw new IllegalArgumentException("does not have a public no-argument constructor");
+            }
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Invalid %s '%s'; accepted values are 'random', 'description', or a public RuleViolationFileNameStrategy with a public no-argument constructor",
+                    FILE_NAMES_PROPERTY_NAME, configured), e);
+        }
+    }
