+    private StoreState getStoreState(File folder) {
+        try {
+            String path = new File(folder, STORED_RULES_FILE_NAME).getCanonicalPath();
+            return STORE_STATES_BY_PATH.computeIfAbsent(path, ignored -> new StoreState(folder, new File(folder, STORED_RULES_FILE_NAME)));
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void ensureStoreFolderExists() {
+        Path folderPath = storeFolder.toPath();
+        try {
+            if (!existsWithoutFollowingLinks(folderPath)) {
+                if (!storeFolder.mkdirs() && !isDirectoryWithoutFollowingLinks(folderPath)) {
+                    throw new IOException("Could not create store folder " + storeFolder);
+                }
+            }
+            if (!isDirectoryWithoutFollowingLinks(folderPath)) {
+                throw new IOException("Store path is not a directory: " + storeFolder);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void ensureStoredRulesFile(File storedRulesFile, boolean indexExisted) {
+        Path indexPath = storedRulesFile.toPath();
+        if (!indexExisted) {
+            if (!storeCreationAllowed || integrityMode == IntegrityMode.FAIL) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+            }
+            try {
+                if (!storedRulesFile.createNewFile() && !existsWithoutFollowingLinks(indexPath)) {
+                    throw new IOException("Could not create index file " + storedRulesFile);
+                }
+            } catch (IOException e) {
+                throw new StoreInitializationFailedException(e);
+            }
+        }
+
+        try {
+            Path folderPath = storeFolder.toPath().toAbsolutePath().normalize();
+            Path indexAbsolutePath = indexPath.toAbsolutePath().normalize();
+            if (!indexAbsolutePath.getParent().equals(folderPath)
+                    || !Files.isRegularFile(indexPath, LinkOption.NOFOLLOW_LINKS)) {
+                throw new IOException("Index is not a regular file directly in the store folder");
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Violation store index must be a regular file directly in %s: %s", storeFolder, storedRulesFile));
+        }
+    }
