+    private IntegrityReport analyzeIntegrity(FileSyncedProperties rules) {
+        List<EntryAnalysis> entries = rules.entries().stream()
+                .sorted(Comparator.comparing(entry -> entry.description))
+                .map(entry -> analyzeEntry(entry, rules))
+                .collect(toList());
+
+        Map<String, List<EntryAnalysis>> entriesByRecordedName = groupBy(entries, entry -> entry.recordedName);
+        Map<String, List<EntryAnalysis>> entriesByTarget = groupBy(entries, entry -> entry.target == null ? null : entry.target.toString());
+        Map<String, List<EntryAnalysis>> entriesByDerivedName = groupBy(entries, entry -> entry.derivedName);
+
+        for (EntryAnalysis entry : entries) {
+            List<EntryAnalysis> sameName = entriesByRecordedName.get(entry.recordedName);
+            List<EntryAnalysis> sameTarget = entry.target == null ? null : entriesByTarget.get(entry.target.toString());
+            entry.shared = sameName.size() > 1 || sameTarget != null && sameTarget.size() > 1;
+            List<EntryAnalysis> sameDerivedName = entry.derivedName == null ? null : entriesByDerivedName.get(entry.derivedName);
+            entry.colliding = sameDerivedName != null && sameDerivedName.size() > 1;
+        }
+
+        Set<String> recordedNames = new HashSet<>();
+        for (EntryAnalysis entry : entries) {
+            recordedNames.add(entry.recordedName);
+        }
+        for (EntryAnalysis entry : entries) {
+            entry.occupied = isOccupied(entry, recordedNames, entries);
+        }
+
+        List<File> unownedFiles = findUnownedFiles(entries);
+        return new IntegrityReport(entries, unownedFiles);
+    }
+
+    private EntryAnalysis analyzeEntry(IndexEntry entry, FileSyncedProperties rules) {
+        EntryAnalysis result = new EntryAnalysis(entry);
+        result.path = resolvePath(entry.recordedName);
+        result.target = result.path.realPath;
+        result.broken = result.path.broken;
+        result.derivedName = deriveName(entry.description);
+        result.misplaced = !isRandomNaming() && !entry.recordedName.equals(result.derivedName);
+
+        if (!result.broken && isIndex(result.target)) {
+            result.broken = true;
+        }
+        if (!result.broken) {
+            try {
+                result.resolved = readLines(result.target).isEmpty();
+            } catch (RuntimeException e) {
+                result.broken = true;
+            }
+        }
+        return result;
+    }
+
+    private boolean isOccupied(EntryAnalysis entry, Set<String> recordedNames, List<EntryAnalysis> entries) {
+        if (entry.derivedName == null) {
+            return true;
+        }
+        Path derivedPath = resolvePath(entry.derivedName).realPath;
+        if (derivedPath == null || !isDirectChild(derivedPath) || isIndex(derivedPath)) {
+            return true;
+        }
+
+        for (EntryAnalysis other : entries) {
+            if (other != entry && entry.derivedName.equals(other.recordedName)) {
+                return true;
+            }
+        }
+
+        Path source = entry.target;
+        if (!existsWithoutFollowingLinks(derivedPath)) {
+            return false;
+        }
+        if (source != null && sameFile(source, derivedPath)) {
+            return false;
+        }
+        return true;
+    }
+
+    private List<File> findUnownedFiles(List<EntryAnalysis> entries) {
+        List<File> result = new ArrayList<>();
+        Set<Path> ownedTargets = new HashSet<>();
+        for (EntryAnalysis entry : entries) {
+            if (!entry.broken && entry.target != null && Files.isRegularFile(entry.target)) {
+                ownedTargets.add(entry.target);
+            }
+        }
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(storeFolder.toPath())) {
+            for (Path file : files) {
+                if (isIndex(file) || !Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)) {
+                    continue;
+                }
+                boolean owned = ownedTargets.stream().anyMatch(target -> sameFile(target, file));
+                if (!owned) {
+                    result.add(file.toFile());
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        result.sort(Comparator.comparing(File::getName));
+        return result;
+    }
+
+    private void repair(IntegrityReport report, FileSyncedProperties rules) {
+        boolean changed = false;
+        for (EntryAnalysis entry : report.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                rules.remove(entry.description);
+                changed = true;
+            } else if (entry.resolved) {
+                deleteEntryFile(entry);
+                rules.remove(entry.description);
+                changed = true;
+            }
+        }
+
+        for (EntryAnalysis entry : report.entries) {
+            if (entry.shared || entry.broken || entry.resolved || !entry.misplaced || entry.colliding || entry.occupied) {
+                continue;
+            }
+            moveEntryFile(entry);
+            rules.set(entry.description, entry.derivedName);
+            changed = true;
+        }
+        if (changed) {
+            rules.syncFileSystem();
+        }
+    }
+
+    private void deleteEntryFile(EntryAnalysis entry) {
+        if (entry.target == null || isIndex(entry.target)) {
+            return;
+        }
+        try {
+            Files.deleteIfExists(entry.target);
+            if (entry.path.recordedPath != null && !samePath(entry.path.recordedPath, entry.target)
+                    && Files.isSymbolicLink(entry.path.recordedPath)) {
+                Files.deleteIfExists(entry.path.recordedPath);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not delete resolved violation file for rule '%s'", entry.description), e);
+        }
+    }
+
+    private void moveEntryFile(EntryAnalysis entry) {
+        Path source = entry.target;
+        Path destination = resolvePath(entry.derivedName).recordedPath;
+        if (source == null || destination == null || !isDirectChild(destination) || isIndex(destination)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot move violation file for rule '%s' to '%s'", entry.description, entry.derivedName));
+        }
+        try {
+            if (!sameFile(source, destination)) {
+                Files.move(source, destination, StandardCopyOption.ATOMIC_MOVE);
+            }
+            if (entry.path.recordedPath != null && !samePath(entry.path.recordedPath, source)
+                    && Files.isSymbolicLink(entry.path.recordedPath)) {
+                Files.deleteIfExists(entry.path.recordedPath);
+            }
+        } catch (IOException atomicMoveFailure) {
+            try {
+                if (!sameFile(source, destination)) {
+                    Files.move(source, destination);
+                }
+                if (entry.path.recordedPath != null && !samePath(entry.path.recordedPath, source)
+                        && Files.isSymbolicLink(entry.path.recordedPath)) {
+                    Files.deleteIfExists(entry.path.recordedPath);
+                }
+            } catch (IOException e) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Could not move violation file for rule '%s' to '%s'", entry.description, entry.derivedName), e);
+            }
+        }
+    }
