+    @Override
+    public boolean contains(ArchRule rule) {
+        return storeState.storedRules.containsKey(rule.getDescription());
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+        synchronized (storeState) {
+            if (integrityMode == IntegrityMode.REPAIR && violations.isEmpty()) {
+                forgetRuleIfKnown(rule.getDescription());
+                return;
+            }
+
+            String ruleDescription = rule.getDescription();
+            String existingFileName = storeState.storedRules.getProperty(ruleDescription);
+            String ruleFileName = existingFileName == null ? deriveName(ruleDescription) : existingFileName;
+            validateSavePath(ruleFileName, existingFileName);
+            Path ruleDetails = storeFolder.toPath().resolve(ruleFileName).normalize();
+            write(violations, ruleDetails, existingFileName != null);
+            if (existingFileName == null) {
+                storeState.storedRules.set(ruleDescription, ruleFileName);
+                storeState.storedRules.syncFileSystem();
+            }
+        }
+    }
+
+    private void forgetRuleIfKnown(String ruleDescription) {
+        String existingFileName = storeState.storedRules.getProperty(ruleDescription);
+        if (existingFileName == null) {
+            return;
+        }
+
+        EntryAnalysis entry = analyzeEntry(new IndexEntry(ruleDescription, existingFileName), storeState.storedRules);
+        boolean shared = storeState.storedRules.entries().stream()
+                .filter(other -> !other.description.equals(ruleDescription))
+                .map(other -> analyzeEntry(other, storeState.storedRules))
+                .anyMatch(other -> sharesFile(entry, other));
+        if (!shared && !entry.broken) {
+            deleteEntryFile(entry);
+        }
+        storeState.storedRules.remove(ruleDescription);
+        storeState.storedRules.syncFileSystem();
+    }
+
+    private boolean sharesFile(EntryAnalysis first, EntryAnalysis second) {
+        return first.target != null && second.target != null && sameFile(first.target, second.target)
+                || first.recordedName.equals(second.recordedName);
+    }
+
+    private void validateSavePath(String ruleFileName, String existingFileName) {
+        if (ruleFileName == null || ruleFileName.length() == 0) {
+            throw new StoreUpdateFailedException("The rule violation file name strategy yielded no name");
+        }
+        Path path = storeFolder.toPath().resolve(ruleFileName).normalize();
+        if (!isDirectChild(path) || isIndex(path)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Refusing to write violation file '%s' outside the store's direct files", ruleFileName));
+        }
+        if (existingFileName == null) {
+            for (IndexEntry entry : storeState.storedRules.entries()) {
+                if (ruleFileName.equals(entry.recordedName)) {
+                    throw new StoreUpdateFailedException(String.format(
+                            "Violation file '%s' is already recorded by another rule", ruleFileName));
+                }
+            }
+            if (existsWithoutFollowingLinks(path)) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Refusing to overwrite existing violation file '%s'", ruleFileName));
+            }
+        } else {
+            if (existsWithoutFollowingLinks(path) && !Files.isRegularFile(path)) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Refusing to overwrite non-file violation path '%s'", ruleFileName));
+            }
+            ResolvedPath resolved = resolvePath(existingFileName);
+            if (resolved.broken && existsWithoutFollowingLinks(path)) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Refusing to write through unsafe violation path '%s'", existingFileName));
+            }
+            if (resolved.realPath != null && !isDirectChild(resolved.realPath)) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Refusing to write outside the store through violation path '%s'", existingFileName));
+            }
+        }
+    }
+
+    private void write(List<String> violations, Path ruleDetails, boolean existingEntry) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        try {
+            Files.write(ruleDetails, builder.toString().getBytes(UTF_8));
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        String ruleDetailsFileName = storeState.storedRules.getProperty(rule.getDescription());
+        checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+        List<String> result = readLines(ruleDetailsFileName);
+        log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+        return result;
+    }
+
+    private List<String> readLines(String ruleDetailsFileName) {
+        return readLines(resolvePath(ruleDetailsFileName).realPath);
+    }
+
+    private List<String> readLines(Path ruleDetailsFile) {
+        String violationsText = readStoreFile(ruleDetailsFile);
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(Path file) {
+        try {
+            String result = new String(toByteArray(file.toFile()), UTF_8);
+            return ensureUnixLineBreaks(result.replace("\r", "\n"));
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private String deriveName(String description) {
+        if (isRandomNaming()) {
+            return null;
+        }
+        String result = ruleViolationFileNameStrategy.createRuleFileName(description);
+        if (result == null || result.length() == 0) {
+            throw new StoreInitializationFailedException("The rule violation file name strategy yielded no name for rule '" + description + "'");
+        }
+        return result;
+    }
+
+    private boolean isRandomNaming() {
+        return !hasConstructorStrategy && ruleViolationFileNameStrategy == constructorStrategy;
+    }
+
+    private ResolvedPath resolvePath(String fileName) {
+        if (fileName == null) {
+            return ResolvedPath.broken(null);
+        }
+        Path folderPath = storeFolder.toPath().toAbsolutePath().normalize();
+        Path recordedPath = folderPath.resolve(fileName).normalize();
+        if (!isDirectOrInside(folderPath, recordedPath)) {
+            return ResolvedPath.broken(recordedPath);
+        }
+
+        Path realPath = existingRealPath(recordedPath);
+        if (realPath == null) {
+            return ResolvedPath.broken(recordedPath);
+        }
+        boolean regular = Files.isRegularFile(realPath);
+        boolean direct = isDirectChild(realPath);
+        return new ResolvedPath(recordedPath, realPath, !regular || !direct);
+    }
+
+    private Path existingRealPath(Path path) {
+        try {
+            if (existsWithoutFollowingLinks(path)) {
+                return path.toRealPath();
+            }
+            Path current = path;
+            List<Path> suffix = new ArrayList<>();
+            while (current != null && !existsWithoutFollowingLinks(current)) {
+                suffix.add(current.getFileName());
+                current = current.getParent();
+            }
+            if (current == null) {
+                return path;
+            }
+            Path realCurrent = current.toRealPath();
+            for (int i = suffix.size() - 1; i >= 0; i--) {
+                realCurrent = realCurrent.resolve(suffix.get(i));
+            }
+            return realCurrent.normalize();
+        } catch (IOException e) {
+            return path;
+        }
+    }
+
+    private boolean isDirectOrInside(Path folderPath, Path path) {
+        return path.startsWith(folderPath);
+    }
+
+    private boolean isDirectChild(Path path) {
+        Path absolute = path.toAbsolutePath().normalize();
+        Path folderPath = storeFolder.toPath().toAbsolutePath().normalize();
+        return folderPath.equals(absolute.getParent());
+    }
+
+    private boolean isIndex(Path path) {
+        return path != null && samePath(path.toAbsolutePath().normalize(), storeFolder.toPath().resolve(STORED_RULES_FILE_NAME).toAbsolutePath().normalize());
+    }
+
+    private static boolean existsWithoutFollowingLinks(Path path) {
+        return Files.exists(path, LinkOption.NOFOLLOW_LINKS);
+    }
+
+    private static boolean isDirectoryWithoutFollowingLinks(Path path) {
+        return Files.isDirectory(path, LinkOption.NOFOLLOW_LINKS);
+    }
+
+    private static boolean samePath(Path first, Path second) {
+        return first.toAbsolutePath().normalize().equals(second.toAbsolutePath().normalize());
+    }
+
+    private static boolean sameFile(Path first, Path second) {
+        try {
+            return Files.isSameFile(first, second);
+        } catch (IOException e) {
+            return samePath(first, second);
+        }
+    }
+
+    private static <T> Map<T, List<EntryAnalysis>> groupBy(List<EntryAnalysis> entries, FunctionWithEntry<T> function) {
+        Map<T, List<EntryAnalysis>> result = new HashMap<>();
+        for (EntryAnalysis entry : entries) {
+            T key = function.apply(entry);
+            if (key != null) {
+                result.computeIfAbsent(key, ignored -> new ArrayList<>()).add(entry);
+            }
+        }
+        return result;
+    }
+
+    private static String createDescriptionBasedFileName(String description) {
+        List<String> words = new ArrayList<>();
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
+        while (matcher.find()) {
+            words.add(matcher.group());
+        }
+        String first = words.isEmpty() ? "rule" : words.get(0);
+        String last = words.isEmpty() ? "rule" : words.get(words.size() - 1);
+        String hash = sha256(description).substring(0, 24);
+        int stemLength = MAX_BUILT_IN_FILE_NAME_LENGTH - hash.length() - 1;
+        String stem = first.equals(last) ? trimWord(first, stemLength) : trimPair(first, last, stemLength);
+        String result = stem + "-" + hash;
+        if (STORED_RULES_FILE_NAME.equals(result)) {
+            result = "rule-" + hash;
+        }
+        return result;
+    }
+
+    private static String trimWord(String word, int maxLength) {
+        if (word.length() <= maxLength) {
+            return word;
+        }
+        return word.substring(0, Math.max(4, maxLength));
+    }
+
+    private static String trimPair(String first, String last, int maxLength) {
+        if (first.length() + last.length() + 1 <= maxLength) {
+            return first + "-" + last;
+        }
+        int firstLength = Math.max(4, (maxLength - 1) / 2);
+        int lastLength = Math.max(4, maxLength - 1 - firstLength);
+        if (firstLength + lastLength + 1 > maxLength) {
+            lastLength = maxLength - firstLength - 1;
+        }
+        return first.substring(0, Math.min(first.length(), firstLength))
+                + "-"
+                + last.substring(0, Math.min(last.length(), lastLength));
+    }
+
+    private static String sha256(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder();
+            for (byte b : digest) {
+                result.append(String.format("%02x", b & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new IllegalStateException(e);
+        }
+    }
+
+    private enum IntegrityMode {
+        IGNORE,
+        REPAIR,
+        FAIL;
+
+        static IntegrityMode from(String value) {
+            if (INTEGRITY_IGNORE.equals(value)) {
+                return IGNORE;
+            }
+            if (INTEGRITY_REPAIR.equals(value)) {
+                return REPAIR;
+            }
+            if (INTEGRITY_FAIL.equals(value)) {
+                return FAIL;
+            }
+            throw new StoreInitializationFailedException(String.format(
+                    "Invalid %s '%s'; accepted values are 'repair', 'fail', and 'ignore'", INTEGRITY_PROPERTY_NAME, value));
+        }
+    }
+
+    private static class StoreState {
+        private final File storedRulesFile;
+        private FileSyncedProperties storedRules;
+
+        StoreState(File storeFolder, File storedRulesFile) {
+            this.storedRulesFile = storedRulesFile;
+        }
+    }
+
+    private static class FileSyncedProperties {
+        private final File propertiesFile;
+        private final Properties loadedProperties;
+
+        private FileSyncedProperties(File file, Properties properties) {
+            propertiesFile = file;
+            loadedProperties = properties;
+        }
+
+        static FileSyncedProperties load(File file) {
+            Properties result = new Properties();
+            try (FileInputStream inputStream = new FileInputStream(file)) {
+                result.load(inputStream);
+                return new FileSyncedProperties(file, result);
+            } catch (IOException e) {
+                throw new StoreInitializationFailedException(e);
+            }
+        }
